insert into public.spark_subjects (id, name, short_name, qualification, mark, description, enabled, status, sort_order, implementation, study_view, capabilities, routes, stats, learning_config, manifest_version) values
  ('geography', 'CSEC Geography', 'Geography', 'CSEC', 'GE', 'Read maps, explore Caribbean landscapes and settlements, and prepare for CSEC through diagrams, fieldwork and exam practice.', false, 'draft', 53, 'generic', 'study', '{"study":true,"practice":true,"flashcards":true,"progress":true,"paper1":true,"paper2":true,"adaptive":false,"structured":true,"labs":true,"sba":true}'::jsonb, '{"study":"/study/geography","practice":"/practice/geography","flashcards":"/dashboard/flashcards/geography","progress":"/dashboard/progress"}'::jsonb, '{"sections":3,"topics":25,"flashcards":50,"paper1Items":60,"paper2PracticeSets":1}'::jsonb, '{"syllabusUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf","syllabusCode":"CXC 02/G/SYLL 15"}'::jsonb, 1)
insert into public.spark_subject_sections (subject_id, section_id, title, description, sort_order, enabled, metadata) values
