insert into public.spark_subject_topics (subject_id, topic_id, section_id, title, description, sort_order, enabled, metadata) values
  ('geography', 'geo-symbols-and-references', 'geo-map-skills', 'Map symbols and grid references', 'A topographic map shows the shape of the land and where features are. Use the key to turn a symbol into evidence about a place.', 0, true, '{"syllabus":{"objectives":["I 1(a–b)"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"A topographic map shows the shape of the land and where features are. Use the key to turn a symbol into evidence about a place.","sections":[{"title":"Use the key","paragraphs":["A blue line may be a stream, and a broken line may be a footpath. Read the key on this map before naming the feature. If asked for a land use, connect the symbol to an activity such as cultivation, transport or settlement."]},{"title":"Read right, then up","paragraphs":["Eastings are the numbered vertical grid lines. Northings are the numbered horizontal lines. A four-figure reference identifies a square using its bottom-left corner. For a six-figure reference, divide the square into tenths. Read the two easting digits and its tenths digit, then the two northing digits and its tenths digit."]},{"title":"Avoid the line on the far side","paragraphs":["Start from the grid line immediately west and the line immediately south of the point. Write both groups with the same number of digits, including leading zeros."]}],"workedExample":{"title":"Worked example","prompt":"A school lies in square 4732, six tenths east of grid line 47 and three tenths north of line 32.","answer":"Write 476 for the easting and 323 for the northing. The reference is 476323."},"check":{"question":"What area does 4732 identify?","answer":"The square immediately east of line 47 and north of line 32."},"flashcards":[{"id":"geo-symbols-and-references-check","front":"What area does 4732 identify?","back":"The square immediately east of line 47 and north of line 32."},{"id":"geo-symbols-and-references-apply","front":"A school lies in square 4732, six tenths east of grid line 47 and three tenths north of line 32.","back":"Write 476 for the easting and 323 for the northing. The reference is 476323."}]}}'::jsonb),
  ('geography', 'geo-direction-and-scale', 'geo-map-skills', 'Compass direction, bearings and distance', 'Locate the place you start from. Direction, bearing and distance all depend on that starting point.', 1, true, '{"syllabus":{"objectives":["I 1(c–e)"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Locate the place you start from. Direction, bearing and distance all depend on that starting point.","sections":[{"title":"Compass and bearing","paragraphs":["Use the 16-point compass for names such as ENE and SSW. For a grid bearing, draw a line from the start to the destination. Measure clockwise from grid north at the start and write three digits from 000° to 359°. Reversing a bearing changes it by 180°."]},{"title":"Straight and curved distance","paragraphs":["Measure a straight line with a ruler. For a curved road, mark successive short segments on a paper strip, or trace it with thread and straighten the thread. Use the map scale to turn the total into ground distance."]},{"title":"Work with the scale on screen","paragraphs":["At 1:25,000, 1 cm on the original map is 250 m on the ground. A screenshot can resize, so compare the route with the printed scale bar in the same image. Keep units consistent before converting."]}],"workedExample":{"title":"Worked example","prompt":"A track measures 7.6 cm on a 1:25,000 print.","answer":"7.6 × 25,000 = 190,000 cm = 1,900 m = 1.9 km."},"check":{"question":"What is the reverse bearing of 075°?","answer":"255°. Add 180° to 075°."},"flashcards":[{"id":"geo-direction-and-scale-check","front":"What is the reverse bearing of 075°?","back":"255°. Add 180° to 075°."},{"id":"geo-direction-and-scale-apply","front":"A track measures 7.6 cm on a 1:25,000 print.","back":"7.6 × 25,000 = 190,000 cm = 1,900 m = 1.9 km."}]}}'::jsonb),
  ('geography', 'geo-contours-and-profiles', 'geo-map-skills', 'Contours, cross sections and gradients', 'Contour lines join places of equal height. Their spacing shows how quickly the land rises or falls.', 2, true, '{"syllabus":{"objectives":["I 1(f–i)"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Contour lines join places of equal height. Their spacing shows how quickly the land rises or falls.","sections":[{"title":"Read slope and landforms","paragraphs":["Close contours show a steep slope. Widely spaced contours show a gentle slope. Nested closed contours rising towards the centre usually show a hill. A contour V that crosses a stream points upstream. A ridge can form a V pointing downhill."]},{"title":"Draw the profile","paragraphs":["Put a strip along the cross-section line and mark every contour crossing with its height. Transfer the marks to distance along the horizontal axis and height on the vertical axis. Join the points smoothly. Label the ends, scales and units. Show breaks of slope when sketching."]},{"title":"Gradient and resizing","paragraphs":["Gradient is vertical rise divided by horizontal distance. Convert both to metres. For a map copy, transfer features square by square. Doubling every side of a 1:50,000 map makes the new scale 1:25,000. Keep the same proportions on a reduction."]}],"workedExample":{"title":"Worked example","prompt":"A path rises from 120 m to 280 m over 2 km.","answer":"Rise = 160 m. Run = 2,000 m. Divide both by 160 to get a gradient of 1 in 12.5."},"check":{"question":"If adjacent contours are 20 m apart in height and four intervals separate two points, what is the height change?","answer":"80 m. Count the intervals between lines."},"flashcards":[{"id":"geo-contours-and-profiles-check","front":"If adjacent contours are 20 m apart in height and four intervals separate two points, what is the height change?","back":"80 m. Count the intervals between lines."},{"id":"geo-contours-and-profiles-apply","front":"A path rises from 120 m to 280 m over 2 km.","back":"Rise = 160 m. Run = 2,000 m. Divide both by 160 to get a gradient of 1 in 12.5."}]}}'::jsonb),
  ('geography', 'geo-landscape-evidence', 'geo-map-skills', 'Relief, drainage, land use and photographs', 'Describe what you can see, locate it precisely, then explain the relationship between features.', 3, true, '{"syllabus":{"objectives":["I 1(j–k), I 2"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Describe what you can see, locate it precisely, then explain the relationship between features.","sections":[{"title":"Describe the physical landscape","paragraphs":["Use contour labels and spacing for elevation and slope. For drainage, describe stream direction, pattern, tributaries and water bodies. A river can turn sharply without flowing uphill. Compare contour heights at two points to check its direction."]},{"title":"Read settlement and land use","paragraphs":["Linear settlement follows a road, coast or valley. Nucleated settlement clusters at a junction or service centre. Dispersed buildings are scattered. Use evidence such as fields, mangroves, forest, buildings or quarry symbols."]},{"title":"Use photographs with care","paragraphs":["A ground photograph shows detail but can hide land behind a hill or building. An oblique aerial image looks down at an angle. A vertical image is useful for patterns and relative position. Describe foreground, middle ground and background, or label evidence on a sketch."]}],"workedExample":{"title":"Worked example","prompt":"Houses follow a flat river terrace above a narrow floodplain.","answer":"Describe the linear pattern and its position first. The terrace may provide buildable land and road access while reducing exposure to ordinary river floods."},"check":{"question":"How can you explain land use from a map without guessing?","answer":"Name a visible feature and link it to a plausible process. Qualify what the map alone cannot show."},"flashcards":[{"id":"geo-landscape-evidence-check","front":"How can you explain land use from a map without guessing?","back":"Name a visible feature and link it to a plausible process. Qualify what the map alone cannot show."},{"id":"geo-landscape-evidence-apply","front":"Houses follow a flat river terrace above a narrow floodplain.","back":"Describe the linear pattern and its position first. The terrace may provide buildable land and road access while reducing exposure to ordinary river floods."}]}}'::jsonb),
  ('geography', 'geo-coordinates-and-time', 'geo-map-skills', 'Latitude, longitude and Caribbean location', 'Latitude is distance north or south of the Equator. Longitude is distance east or west of the Prime Meridian.', 4, true, '{"syllabus":{"objectives":["I 4"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Latitude is distance north or south of the Equator. Longitude is distance east or west of the Prime Meridian.","sections":[{"title":"Find a point","paragraphs":["Read latitude first and longitude second. Parallels run east–west and measure north or south. Meridians meet at the poles and measure east or west. Know the Equator, Tropics of Cancer and Capricorn, Arctic and Antarctic Circles, Prime Meridian and 180° meridian."]},{"title":"Calculate standard time","paragraphs":["Earth turns 360° in 24 hours, so 15° of longitude corresponds to one hour and 1° to four minutes. Add time going east and subtract going west. If the question supplies time-zone offsets, use those. Real time-zone boundaries and daylight saving are political rules."]},{"title":"Sketch the region","paragraphs":["Use north, a title, a legend and relative position. Cuba lies west of Hispaniola. Jamaica lies south of eastern Cuba, Puerto Rico east of Hispaniola, and the Lesser Antilles curve towards Trinidad. Belize is in Central America. Guyana lies on the northern coast of South America."]}],"workedExample":{"title":"Worked example","prompt":"Place A is at 75° W and B at 60° W. At A the exercise uses 09:00 local solar time.","answer":"B is 15° east of A. Add one hour to get 10:00 at B."},"check":{"question":"Which coordinate changes when you travel due north along a meridian?","answer":"Latitude changes. Longitude stays the same."},"flashcards":[{"id":"geo-coordinates-and-time-check","front":"Which coordinate changes when you travel due north along a meridian?","back":"Latitude changes. Longitude stays the same."},{"id":"geo-coordinates-and-time-apply","front":"Place A is at 75° W and B at 60° W. At A the exercise uses 09:00 local solar time.","back":"B is 15° east of A. Add one hour to get 10:00 at B."}]}}'::jsonb),
  ('geography', 'geo-weather-maps-and-graphs', 'geo-map-skills', 'Weather maps, climate graphs and statistics', 'The first things to read are the title, date, axes, units and key. Every comparison should use the same unit and time period.', 5, true, '{"syllabus":{"objectives":["I 3, I 5"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"The first things to read are the title, date, axes, units and key. Every comparison should use the same unit and time period.","sections":[{"title":"Weather maps","paragraphs":["An isobar joins points of equal air pressure, usually in hPa. Find a high or low from the sequence of values. Closely spaced isobars usually mean a strong pressure gradient and stronger wind. Use the key for fronts, winds and precipitation symbols."]},{"title":"Climate graphs and statistical maps","paragraphs":["Climate graphs often show monthly rainfall as bars and temperature as a line on separate axes. Add rainfall values for annual rainfall and subtract the lowest temperature from the highest for annual range. In a choropleth map, the key gives intervals. A dot map may use one dot for many people."]},{"title":"Display and summarise data","paragraphs":["Use a line graph for a series over time, bars for categories and a pie chart for shares of a total. Calculate a sector angle as category ÷ total × 360°. Mean is total ÷ count, median is the middle of an ordered list, and mode is the most frequent value. A table needs headings and units."]}],"workedExample":{"title":"Worked example","prompt":"River depths at five sites are 10, 11, 11, 12 and 36 cm.","answer":"Mean = 16 cm, median = 11 cm and mode = 11 cm. The deep site pulls the mean upwards, so the median better describes the typical site here."},"check":{"question":"Which rainfall value goes in the annual total?","answer":"All 12 monthly rainfall values are added. Temperature range is a separate calculation."},"flashcards":[{"id":"geo-weather-maps-and-graphs-check","front":"Which rainfall value goes in the annual total?","back":"All 12 monthly rainfall values are added. Temperature range is a separate calculation."},{"id":"geo-weather-maps-and-graphs-apply","front":"River depths at five sites are 10, 11, 11, 12 and 36 cm.","back":"Mean = 16 cm, median = 11 cm and mode = 11 cm. The deep site pulls the mean upwards, so the median better describes the typical site here."}]}}'::jsonb),
  ('geography', 'geo-fieldwork-and-sba', 'geo-map-skills', 'Plan, carry out and report fieldwork', 'A field study starts with a question about a real place that you can answer with observations or measurements.', 6, true, '{"syllabus":{"objectives":["I 6, Paper 031 and Paper 032"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"A field study starts with a question about a real place that you can answer with observations or measurements.","sections":[{"title":"Plan your method","paragraphs":["Define a small study area, map it, and choose safe sites with your teacher. Use primary evidence that you collect and secondary evidence from named sources. Random sampling limits selection bias. Systematic sampling uses a fixed interval. Stratified sampling represents defined groups or zones."]},{"title":"Collect evidence consistently","paragraphs":["Keep units, method and observation period the same across sites. Record the date, weather, location and instrument. Repeat measurements where possible. A pilot can reveal an ambiguous survey question or an unsafe site before the main study."]},{"title":"Write a report that answers the question","paragraphs":["State the aim, locate the study, explain the method, present labelled evidence, and analyse the pattern and exceptions. Finish with an evidence-based conclusion, limitations, and improvements. Use the CXC strategy sheet and confirm your school''s submission requirements. Paper 032 tests these skills through a supplied investigation."]}],"workedExample":{"title":"Worked example","prompt":"You investigate whether infiltration differs between a playing field and a planted strip.","answer":"Use the same ring, water volume and timing at several points in each area. Report median times, note rainfall and compaction, and explain why one school cannot represent every surface."},"check":{"question":"How could you reduce observer bias in a traffic count?","answer":"Use defined vehicle categories, equal counting periods and repeated counts. Compare counts at the same time of day."},"flashcards":[{"id":"geo-fieldwork-and-sba-check","front":"How could you reduce observer bias in a traffic count?","back":"Use defined vehicle categories, equal counting periods and repeated counts. Compare counts at the same time of day."},{"id":"geo-fieldwork-and-sba-apply","front":"You investigate whether infiltration differs between a playing field and a planted strip.","back":"Use the same ring, water volume and timing at several points in each area. Report median times, note rainfall and compaction, and explain why one school cannot represent every surface."}]}}'::jsonb),
  ('geography', 'geo-earth-and-plates', 'geo-natural-systems', 'Earth structure, plates and their boundaries', 'Tectonic plates are pieces of the rigid lithosphere. Their motion helps explain where earthquakes, volcanoes and mountain belts cluster.', 7, true, '{"syllabus":{"objectives":["II 1–3"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Tectonic plates are pieces of the rigid lithosphere. Their motion helps explain where earthquakes, volcanoes and mountain belts cluster.","sections":[{"title":"Inside Earth","paragraphs":["The crust is the thin outer rock layer. Oceanic crust is generally thinner and denser than continental crust. The mantle is mainly solid rock that deforms over long periods. The outer core is liquid metal and the inner core solid metal. The lithosphere includes the crust and rigid uppermost mantle."]},{"title":"Compare the boundaries","paragraphs":["At a divergent boundary, plates separate and magma can build new crust. At a convergent boundary, a denser oceanic plate can descend into the mantle, forming a trench and feeding volcanism above it. Continent–continent collision can build fold mountains. At a transform boundary, plates slide past and can generate shallow earthquakes."]},{"title":"Apply it to the Caribbean","paragraphs":["At the eastern Caribbean margin, oceanic lithosphere descends beneath the Caribbean Plate. This helps explain the Lesser Antilles volcanic arc. Along parts of the northern boundary, lateral motion on faults makes earthquakes a major hazard. A plate map locates the boundary and a cross section explains what happens below it."]}],"workedExample":{"title":"Worked example","prompt":"A deep ocean trench lies east of a curved line of volcanic islands.","answer":"An oceanic plate can be descending westwards beneath another plate. The trench marks the bend in the descending plate and magma can rise on the overriding side."},"check":{"question":"Which boundary creates new oceanic crust?","answer":"A divergent boundary, such as a mid-ocean ridge."},"flashcards":[{"id":"geo-earth-and-plates-check","front":"Which boundary creates new oceanic crust?","back":"A divergent boundary, such as a mid-ocean ridge."},{"id":"geo-earth-and-plates-apply","front":"A deep ocean trench lies east of a curved line of volcanic islands.","back":"An oceanic plate can be descending westwards beneath another plate. The trench marks the bend in the descending plate and magma can rise on the overriding side."}]}}'::jsonb),
  ('geography', 'geo-volcanoes-and-rocks', 'geo-natural-systems', 'Volcanic features and the rock cycle', 'Magma is molten rock underground. It may solidify below the surface or reach the surface as lava.', 8, true, '{"syllabus":{"objectives":["II 4–5"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Magma is molten rock underground. It may solidify below the surface or reach the surface as lava.","sections":[{"title":"Intrusions","paragraphs":["A dyke cuts across pre-existing layers. A sill lies parallel to layers. A plug forms where magma solidifies in a vent, and a batholith is a very large mass formed at depth. Erosion can expose intrusive rocks. Draw the surrounding strata so your diagram shows what a dyke crosses or what a sill follows."]},{"title":"Extrusive forms","paragraphs":["Fluid lava can travel far and build a broad shield. Repeated extensive flows from fissures can build a lava plateau. Viscous magma can trap gas and feed explosive eruptions. Layers of lava and fragments can build a composite cone. A caldera can form when the roof above a drained magma chamber collapses."]},{"title":"Three rock groups","paragraphs":["Igneous rock forms when molten material cools. Sedimentary rock can form when deposited material compacts and cements. Metamorphic rock changes under heat and pressure while remaining solid. Weathering, erosion, burial, melting and uplift connect the groups by many paths."]}],"workedExample":{"title":"Worked example","prompt":"An igneous sheet is parallel to a stack of sedimentary layers.","answer":"It is a sill. Magma spread between layers and then cooled."},"check":{"question":"What transforms limestone into marble?","answer":"Heat and pressure cause recrystallisation without the rock melting."},"flashcards":[{"id":"geo-volcanoes-and-rocks-check","front":"What transforms limestone into marble?","back":"Heat and pressure cause recrystallisation without the rock melting."},{"id":"geo-volcanoes-and-rocks-apply","front":"An igneous sheet is parallel to a stack of sedimentary layers.","back":"It is a sill. Magma spread between layers and then cooled."}]}}'::jsonb),
  ('geography', 'geo-weathering-and-karst', 'geo-natural-systems', 'Weathering, mass movement and limestone', 'Weathering breaks down rock where it lies. Erosion removes material. Mass movement carries material downhill under gravity.', 9, true, '{"syllabus":{"objectives":["II 6–7"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Weathering breaks down rock where it lies. Erosion removes material. Mass movement carries material downhill under gravity.","sections":[{"title":"Weathering processes","paragraphs":["Heating and cooling can stress rock and contribute to exfoliation, where outer sheets peel off. In cold climates, freezing water can widen a joint. Roots can prise open cracks. In warm, moist conditions, hydrolysis can turn minerals such as feldspar into clay. In carbonation, water containing dissolved carbon dioxide dissolves calcium carbonate in limestone."]},{"title":"Limestone at the surface and underground","paragraphs":["Solution widens joints into grikes between blocks called clints. Circular depressions can develop by solution or collapse. Steep-sided hollows between hills are common in Jamaica’s Cockpit Country. Water can disappear into a swallow hole and drain through caves. Calcium carbonate deposited from drips forms stalactites from the roof and stalagmites from the floor. They can join into a pillar."]},{"title":"Explain a slope failure","paragraphs":["A steep, weakened slope can fail after intense rain. Saturated material weighs more, and high pore-water pressure can reduce friction. Clearing vegetation or cutting into a slope can increase the risk. Slow soil creep differs from a rapid slide or flow."]}],"workedExample":{"title":"Worked example","prompt":"Rainwater seeps through a limestone joint.","answer":"Carbonated water dissolves the limestone and gradually widens the joint. Water can then drain further below ground."},"check":{"question":"What is the difference between a stalactite and a stalagmite?","answer":"A stalactite hangs from the roof. A stalagmite grows from the floor."},"flashcards":[{"id":"geo-weathering-and-karst-check","front":"What is the difference between a stalactite and a stalagmite?","back":"A stalactite hangs from the roof. A stalagmite grows from the floor."},{"id":"geo-weathering-and-karst-apply","front":"Rainwater seeps through a limestone joint.","back":"Carbonated water dissolves the limestone and gradually widens the joint. Water can then drain further below ground."}]}}'::jsonb),
  ('geography', 'geo-climate-and-rainfall', 'geo-natural-systems', 'Weather, climate and tropical rainfall', 'Weather describes conditions over a short period. Climate describes long-term patterns and variation.', 10, true, '{"syllabus":{"objectives":["II 8–10"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Weather describes conditions over a short period. Climate describes long-term patterns and variation.","sections":[{"title":"Why climates vary","paragraphs":["Latitude affects sun angle. Temperature usually falls with altitude. The sea heats and cools slowly, so coastal temperature ranges are often smaller. Winds and currents move heat and moisture. Mountains can lift air and leave a drier leeward side."]},{"title":"How rain forms","paragraphs":["As moist air rises, it expands and cools. Water vapour can condense into droplets and precipitation may follow. Convection lifts air heated near the ground. Relief rain forms when hills force air upwards. Along a front, warmer air can be lifted over denser cooler air."]},{"title":"Compare equatorial and tropical marine climate","paragraphs":["Both are generally warm. Equatorial climates typically have abundant rainfall in most months and a small annual temperature range. Many tropical marine Caribbean locations have a clearer wet and dry season, modified by trade winds, altitude and exposure. Use climate graph data to support the comparison."]}],"workedExample":{"title":"Worked example","prompt":"Moist trade winds reach a mountainous island.","answer":"The air rises on the windward side, cools and may produce rain. Descending air on the leeward side warms, so relative humidity drops."},"check":{"question":"Why is a single cool day weak evidence of a change in climate?","answer":"Climate is measured from patterns over many years. One day''s conditions describe weather."},"flashcards":[{"id":"geo-climate-and-rainfall-check","front":"Why is a single cool day weak evidence of a change in climate?","back":"Climate is measured from patterns over many years. One day''s conditions describe weather."},{"id":"geo-climate-and-rainfall-apply","front":"Moist trade winds reach a mountainous island.","back":"The air rises on the windward side, cools and may produce rain. Descending air on the leeward side warms, so relative humidity drops."}]}}'::jsonb),
  ('geography', 'geo-caribbean-weather', 'geo-natural-systems', 'Trade winds, waves, fronts and hurricanes', 'Caribbean weather changes as winds, pressure systems and moist air move across the region.', 11, true, '{"syllabus":{"objectives":["II 11"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Caribbean weather changes as winds, pressure systems and moist air move across the region.","sections":[{"title":"Trade winds, ITCZ and waves","paragraphs":["The north-east trades bring maritime air across much of the Caribbean. Convergence near the ITCZ encourages uplift and showers as the zone shifts seasonally. Easterly waves can bring cloud and thunderstorms. Cold fronts may reach the northern Caribbean and change winds, temperature and rainfall."]},{"title":"Tropical cyclone structure","paragraphs":["Over warm sea, moist air feeds deep thunderstorms around a low-pressure centre. Released latent heat helps sustain the system. In a mature hurricane, strong winds and heavy rain surround the relatively calm eye in the eyewall. Spiral rainbands can cause intense bursts farther out."]},{"title":"Track and impacts","paragraphs":["Read the date and direction of each plotted position. The forecast track is about the centre, while damaging wind and rain cover a wider area. Storm surge raises coastal water. Heavy rainfall can flood rivers and trigger landslides well inland."]}],"workedExample":{"title":"Worked example","prompt":"A coastal community experiences a short calm after violent wind.","answer":"If the eye is passing, the eyewall can return from a different direction. Follow official instructions and remain sheltered."},"check":{"question":"Which hurricane feature usually has the strongest winds?","answer":"The eyewall around the eye."},"flashcards":[{"id":"geo-caribbean-weather-check","front":"Which hurricane feature usually has the strongest winds?","back":"The eyewall around the eye."},{"id":"geo-caribbean-weather-apply","front":"A coastal community experiences a short calm after violent wind.","back":"If the eye is passing, the eyewall can return from a different direction. Follow official instructions and remain sheltered."}]}}'::jsonb),
  ('geography', 'geo-climate-change', 'geo-natural-systems', 'Greenhouse gases, impacts and adaptation', 'The natural greenhouse effect keeps Earth warm enough for life. Human emissions increase the amount of heat retained.', 12, true, '{"syllabus":{"objectives":["II 12–15"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"The natural greenhouse effect keeps Earth warm enough for life. Human emissions increase the amount of heat retained.","sections":[{"title":"Follow the energy","paragraphs":["Incoming sunlight warms the surface. The surface emits infrared energy. Greenhouse gases absorb and re-emit some infrared energy. Burning fossil fuels, land clearing and agriculture change concentrations of carbon dioxide, methane and other gases."]},{"title":"Compare impacts across places","paragraphs":["A low Caribbean island can face coastal flooding, saltwater intrusion and pressure on freshwater or tourism. Parts of the United States also face sea-level rise, while inland regions may face different heat, drought or fire risks. Choose named places and compare the same impact, explaining exposure and capacity to respond."]},{"title":"Mitigation and adaptation","paragraphs":["Mitigation limits future warming by reducing emissions or increasing carbon storage. Adaptation reduces harm from impacts such as flooding or drought. Protecting a mangrove can support both goals. Compare Caribbean early warning, setbacks and water storage with measures used in the United States, using scale and resources in your explanation."]}],"workedExample":{"title":"Worked example","prompt":"A town replaces diesel generation with solar power and raises a road above expected flood levels.","answer":"Solar power reduces emissions, so it is mitigation. Raising the road is adaptation because it reduces expected disruption."},"check":{"question":"How does sea-level rise threaten a coastal well?","answer":"Saltwater can move into the freshwater supply, making it too salty for drinking or crops."},"flashcards":[{"id":"geo-climate-change-check","front":"How does sea-level rise threaten a coastal well?","back":"Saltwater can move into the freshwater supply, making it too salty for drinking or crops."},{"id":"geo-climate-change-apply","front":"A town replaces diesel generation with solar power and raises a road above expected flood levels.","back":"Solar power reduces emissions, so it is mitigation. Raising the road is adaptation because it reduces expected disruption."}]}}'::jsonb),
  ('geography', 'geo-vegetation-and-soils', 'geo-natural-systems', 'Tropical vegetation, forests and latosols', 'Climate, living things, parent material, relief and time shape vegetation and soils together.', 13, true, '{"syllabus":{"objectives":["II 16–19"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Climate, living things, parent material, relief and time shape vegetation and soils together.","sections":[{"title":"Vegetation and environment","paragraphs":["In wet tropical forest, tall layers compete for light. Buttress roots help support some tall trees in shallow rooting zones. Drip tips help shed water. In seasonally dry areas, some trees lose leaves during the dry season. Mangroves tolerate tidal, salty, low-oxygen soils."]},{"title":"Soil components","paragraphs":["Soil contains mineral particles, organic matter, air, water and organisms. In warm humid climates, weathering and decomposition can be rapid. Rain can leach soluble materials, leaving soils rich in iron and aluminium compounds. Iron oxides often give latosols red or yellow colours."]},{"title":"Forest clearing and management","paragraphs":["Leaves and roots intercept rain, protect the surface and help recycle nutrients. Removing cover can increase runoff, soil loss and river sediment. Selective harvesting, replanting and protecting steep catchments can reduce damage. Explain how the measure changes a process."]}],"workedExample":{"title":"Worked example","prompt":"A newly cleared hillside sends muddy water into a stream after a storm.","answer":"Less plant cover leaves soil exposed to raindrop impact. Faster runoff then carries more sediment downhill."},"check":{"question":"Why can a wet tropical forest have luxuriant trees above a heavily leached soil?","answer":"Nutrients recycle quickly between living vegetation and litter. Heavy rain can still remove soluble nutrients from the soil."},"flashcards":[{"id":"geo-vegetation-and-soils-check","front":"Why can a wet tropical forest have luxuriant trees above a heavily leached soil?","back":"Nutrients recycle quickly between living vegetation and litter. Heavy rain can still remove soluble nutrients from the soil."},{"id":"geo-vegetation-and-soils-apply","front":"A newly cleared hillside sends muddy water into a stream after a storm.","back":"Less plant cover leaves soil exposed to raindrop impact. Faster runoff then carries more sediment downhill."}]}}'::jsonb),
  ('geography', 'geo-water-and-drainage', 'geo-natural-systems', 'Water cycle, river processes and drainage patterns', 'A drainage basin is the area that drains to a river and its tributaries. A watershed is the high ground separating neighbouring basins.', 14, true, '{"syllabus":{"objectives":["II 20–21, II 23"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"A drainage basin is the area that drains to a river and its tributaries. A watershed is the high ground separating neighbouring basins.","sections":[{"title":"Stores and transfers","paragraphs":["Evaporation and transpiration move water to the air. Condensation and precipitation return it to the surface. Runoff moves over land, and infiltration moves into soil. Through-flow travels laterally through soil and percolation moves water deeper. An aquifer stores and transmits groundwater. The water table is the upper surface of the saturated zone. A spring occurs where groundwater flows out at the surface."]},{"title":"What a river does","paragraphs":["Hydraulic action and abrasion wear banks or bed. Attrition rounds pieces as they collide, and solution carries dissolved minerals. Traction rolls large material, saltation bounces grains, and suspension carries fine sediment. Deposition happens when transport capacity falls."]},{"title":"Drainage patterns","paragraphs":["Dendritic drainage branches like a tree where rock resistance is fairly uniform. Trellis drainage follows parallel valleys with tributaries joining at near-right angles. Radial streams run away from a high centre such as a volcano. Identify the pattern and connect it to relief or geology."]}],"workedExample":{"title":"Worked example","prompt":"A wooded basin is paved for development.","answer":"Less water infiltrates and runoff reaches channels more rapidly. Peak discharge may rise and occur sooner after heavy rain."},"check":{"question":"What happens to coarse sediment when a river''s velocity drops sharply?","answer":"It tends to settle first because the river has less capacity to transport it."},"flashcards":[{"id":"geo-water-and-drainage-check","front":"What happens to coarse sediment when a river''s velocity drops sharply?","back":"It tends to settle first because the river has less capacity to transport it."},{"id":"geo-water-and-drainage-apply","front":"A wooded basin is paved for development.","back":"Less water infiltrates and runoff reaches channels more rapidly. Peak discharge may rise and occur sooner after heavy rain."}]}}'::jsonb),
  ('geography', 'geo-river-landforms', 'geo-natural-systems', 'Waterfalls, meanders, floodplains and deltas', 'Read the shape of a river feature and explain which parts were eroded and which parts received sediment.', 15, true, '{"syllabus":{"objectives":["II 22"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Read the shape of a river feature and explain which parts were eroded and which parts received sediment.","sections":[{"title":"Waterfalls and gorges","paragraphs":["Where resistant rock overlies weaker rock, the weaker layer can erode faster. A plunge pool undercuts the drop. The overhang can collapse, shifting the waterfall upstream and leaving a gorge."]},{"title":"Meanders and oxbow lakes","paragraphs":["Faster flow erodes the outside bend, while slower flow deposits sediment on the inside. Adjacent bends may narrow the neck. During high flow the river can cut across. Deposition at the old entrances can isolate an oxbow lake."]},{"title":"Floodplains, levees and deltas","paragraphs":["Lateral erosion and deposition help build a flat floodplain. Overbank floods tend to leave coarser material near the channel, forming natural levees. In a braided channel, shifting streams split around sediment bars where a large load and varying flow favour deposition. A delta can build where a river deposits sediment faster than waves and currents remove it, often creating distributaries."]}],"workedExample":{"title":"Worked example","prompt":"On an aerial image, a crescent-shaped water body is separated from the active river.","answer":"Look for an old bend and filled entrances. These support identifying it as an oxbow lake."},"check":{"question":"Where does a point bar build in a meander?","answer":"On the inside bend, where lower velocity favours deposition."},"flashcards":[{"id":"geo-river-landforms-check","front":"Where does a point bar build in a meander?","back":"On the inside bend, where lower velocity favours deposition."},{"id":"geo-river-landforms-apply","front":"On an aerial image, a crescent-shaped water body is separated from the active river.","back":"Look for an old bend and filled entrances. These support identifying it as an oxbow lake."}]}}'::jsonb),
  ('geography', 'geo-coasts-reefs-and-mangroves', 'geo-natural-systems', 'Coastal landforms, coral reefs and mangroves', 'Waves, sediment and coastal ecosystems shape the shoreline together.', 16, true, '{"syllabus":{"objectives":["II 22, II 24–27"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Waves, sediment and coastal ecosystems shape the shoreline together.","sections":[{"title":"Wave erosion and deposition","paragraphs":["Less resistant rock can retreat into bays while resistant headlands remain. Hydraulic action and abrasion erode the foot of a cliff. Collapse and retreat can leave a wave-cut platform. A cave may grow into an arch, then a stack and stump as the rock collapses. Longshore drift moves material when swash approaches at an angle and backwash runs downslope. Deposition builds beaches and spits. A bay-bar joins two sides of a bay, and a tombolo joins an island to another piece of land."]},{"title":"Coral reefs","paragraphs":["Fringing reefs grow near the shore. Barrier reefs are separated from land by a lagoon. Atolls enclose a lagoon with no central high island. Reef-building corals generally need warm, clear, sunlit marine water with suitable salinity and limited sediment. Reefs support fisheries, tourism and coastal protection."]},{"title":"Mangroves","paragraphs":["Mangrove roots trap sediment, reduce wave energy and shelter juvenile fish. Roots and leaves tolerate tidal flooding and salt in different ways. Clearing a mangrove can remove a nursery and increase shoreline exposure. Protecting water flow and limiting pollution support restoration."]}],"workedExample":{"title":"Worked example","prompt":"Waves approach obliquely along a bay and the coast suddenly turns inland.","answer":"Longshore drift can continue carrying sediment across the opening. Lower energy and deposition may extend a spit in the direction of transport."},"check":{"question":"How can you distinguish a barrier reef from a fringing reef on a diagram?","answer":"A barrier reef is separated from the shore by a lagoon. A fringing reef borders the shore."},"flashcards":[{"id":"geo-coasts-reefs-and-mangroves-check","front":"How can you distinguish a barrier reef from a fringing reef on a diagram?","back":"A barrier reef is separated from the shore by a lagoon. A fringing reef borders the shore."},{"id":"geo-coasts-reefs-and-mangroves-apply","front":"Waves approach obliquely along a bay and the coast suddenly turns inland.","back":"Longshore drift can continue carrying sediment across the opening. Lower energy and deposition may extend a spit in the direction of transport."}]}}'::jsonb),
  ('geography', 'geo-hazards-and-risk', 'geo-natural-systems', 'Caribbean hazards and disaster risk', 'A hazard can cause harm. A disaster happens when a hazardous event seriously disrupts an exposed community and exceeds its ability to cope.', 17, true, '{"syllabus":{"objectives":["II 28–30"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"A hazard can cause harm. A disaster happens when a hazardous event seriously disrupts an exposed community and exceeds its ability to cope.","sections":[{"title":"Compare impacts","paragraphs":["Earthquakes shake buildings and can generate landslides or tsunami. Volcanic ash can damage roofs, crops and air transport. Hurricanes combine wind, heavy rain and storm surge. Flooding and landslides depend on both rainfall and local slope, drainage and land use."]},{"title":"Use named examples","paragraphs":["The Lesser Antilles volcanic arc creates eruption risk for islands including Montserrat and St Vincent. Jamaica and Haiti face earthquake risk along active faults. Low coastal settlements face surge, and steep saturated slopes can fail. For an exam answer, name the place and link the specific hazard to its impact."]},{"title":"Reduce exposure and vulnerability","paragraphs":["Families can prepare supplies, know evacuation routes and heed official warnings. Governments can set building standards, maintain shelters and restrict development in exposed zones. Regional cooperation through CDEMA can share information and coordinate support. Distinguish preparedness, immediate response and long-term recovery."]}],"workedExample":{"title":"Worked example","prompt":"Two settlements receive similar rain, but one has homes on steep, recently cleared slopes.","answer":"That settlement has greater exposure to slope failure and more vulnerability where homes lack protection. Rainfall alone does not explain the difference in losses."},"check":{"question":"Give one way to reduce loss from earthquakes before they happen.","answer":"Use and enforce earthquake-resistant building standards or retrofit vulnerable structures."},"flashcards":[{"id":"geo-hazards-and-risk-check","front":"Give one way to reduce loss from earthquakes before they happen.","back":"Use and enforce earthquake-resistant building standards or retrofit vulnerable structures."},{"id":"geo-hazards-and-risk-apply","front":"Two settlements receive similar rain, but one has homes on steep, recently cleared slopes.","back":"That settlement has greater exposure to slope failure and more vulnerability where homes lack protection. Rainfall alone does not explain the difference in losses."}]}}'::jsonb),
  ('geography', 'geo-population-maps', 'geo-human-systems', 'Population distribution, density and pyramids', 'Distribution tells you where people live. Density tells you how many people live in a given area.', 18, true, '{"syllabus":{"objectives":["III 1–2"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Distribution tells you where people live. Density tells you how many people live in a given area.","sections":[{"title":"Explain the pattern","paragraphs":["Flat land, water, ports, roads and jobs can attract people. Steep slopes, flood hazards and poor access can limit settlement. Colonial estates and port towns can shape a pattern long after their original activities change. Compare population clusters with physical and economic evidence."]},{"title":"Choose and read the map","paragraphs":["A dot map shows clusters and gaps. The dots can represent groups of people. A choropleth map uses shaded ranges for rates such as people per square kilometre. Read the key and avoid comparing raw totals across unequal areas as if they were densities."]},{"title":"Read the population pyramid","paragraphs":["Age groups run from youngest at the bottom to oldest at the top. Two bars show the groups on either side. A wide base often reflects many children; a bulge can show a large cohort or migration. Check whether the axis shows numbers or percentages."]}],"workedExample":{"title":"Worked example","prompt":"A parish has 72,000 people and an area of 300 km².","answer":"Density = 72,000 ÷ 300 = 240 people per km². That average does not show where within the parish people cluster."},"check":{"question":"What is the likely implication of a very broad pyramid base for public services?","answer":"A large child population can increase demand for schools and child health services."},"flashcards":[{"id":"geo-population-maps-check","front":"What is the likely implication of a very broad pyramid base for public services?","back":"A large child population can increase demand for schools and child health services."},{"id":"geo-population-maps-apply","front":"A parish has 72,000 people and an area of 300 km².","back":"Density = 72,000 ÷ 300 = 240 people per km². That average does not show where within the parish people cluster."}]}}'::jsonb),
  ('geography', 'geo-population-change-and-migration', 'geo-human-systems', 'Population growth and migration', 'Births, deaths, people arriving and people leaving together determine population change.', 19, true, '{"syllabus":{"objectives":["III 3, III 7"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Births, deaths, people arriving and people leaving together determine population change.","sections":[{"title":"Work out change","paragraphs":["Natural increase is births minus deaths. Net migration is arrivals minus departures. Overall change combines the two. Healthcare and clean water can lower death rates; family size, education and access to reproductive healthcare influence birth rates."]},{"title":"Make a fair comparison","paragraphs":["Compare a Caribbean territory with India using the same period and indicator. Fertility, death rates and migration have varied across both places and over time. A territory can have natural increase and still grow slowly if out-migration is large. For example, a nurse moving from Jamaica to Canada is an emigrant from Jamaica and an immigrant to Canada. Use comparable rates or dated data when available."]},{"title":"Migration has effects at both ends","paragraphs":["Jobs, schooling and family reunion can pull migrants. Unemployment, hazards or limited services can push them. In-migration and out-migration depend on the place being described. Remittances can support households, while losing trained workers can strain services. Receiving areas gain labour but may need more housing."]}],"workedExample":{"title":"Worked example","prompt":"A territory records 2,400 births, 1,500 deaths, 600 arrivals and 1,900 departures.","answer":"Natural increase is 900. Net migration is −1,300. The population falls by 400."},"check":{"question":"How can one move be both immigration and emigration?","answer":"It is emigration from the place left and immigration into the place entered."},"flashcards":[{"id":"geo-population-change-and-migration-check","front":"How can one move be both immigration and emigration?","back":"It is emigration from the place left and immigration into the place entered."},{"id":"geo-population-change-and-migration-apply","front":"A territory records 2,400 births, 1,500 deaths, 600 arrivals and 1,900 departures.","back":"Natural increase is 900. Net migration is −1,300. The population falls by 400."}]}}'::jsonb),
  ('geography', 'geo-urban-settlement', 'geo-human-systems', 'Urbanisation, city growth and sprawl', 'Urbanisation is an increase in the share of people living in urban areas. Urban growth is an increase in urban population or size. Sprawl is spread into surrounding land.', 20, true, '{"syllabus":{"objectives":["III 4–6"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Urbanisation is an increase in the share of people living in urban areas. Urban growth is an increase in urban population or size. Sprawl is spread into surrounding land.","sections":[{"title":"Causes of growth","paragraphs":["Cities grow through natural increase, migration and boundary changes. A capital such as Kingston draws people to jobs, schools, hospitals and transport connections. In Puerto Rico, San Juan''s metropolitan area has expanded along the coastal plain towards Bayamón and Carolina, with transport routes linking surrounding municipalities. Compare specific benefits and problems using a named city."]},{"title":"Benefits and pressures","paragraphs":["A large market supports specialised services and jobs. Fast growth can strain roads, housing, water and waste collection. Outward spread can remove farmland and lengthen commutes. Informal housing may spread into flood-prone or unstable areas when serviced land is expensive."]},{"title":"Management","paragraphs":["Zoning can steer development away from hazard areas. Upgrading housing and drainage can improve existing areas. Public transport can reduce congestion. Locating jobs and services in other towns can reduce pressure on the capital, but transport and employment investment must reach those towns."]}],"workedExample":{"title":"Worked example","prompt":"The urban population rises from 300,000 to 330,000 while the national population rises from 600,000 to 700,000.","answer":"The city grew, but the urban share fell from 50% to about 47%. The share is the measure of urbanisation."},"check":{"question":"How could decentralising jobs reduce pressure on a capital?","answer":"Workers may find employment nearer home, reducing the need to migrate or commute to the capital."},"flashcards":[{"id":"geo-urban-settlement-check","front":"How could decentralising jobs reduce pressure on a capital?","back":"Workers may find employment nearer home, reducing the need to migrate or commute to the capital."},{"id":"geo-urban-settlement-apply","front":"The urban population rises from 300,000 to 330,000 while the national population rises from 600,000 to 700,000.","back":"The city grew, but the urban share fell from 50% to about 47%. The share is the measure of urbanisation."}]}}'::jsonb),
  ('geography', 'geo-resources-and-industry', 'geo-human-systems', 'Economic sectors, resources and industry location', 'Primary activities extract or grow materials. Secondary activities turn them into products. Tertiary activities provide services.', 21, true, '{"syllabus":{"objectives":["III 8–12"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Primary activities extract or grow materials. Secondary activities turn them into products. Tertiary activities provide services.","sections":[{"title":"Follow a product through the economy","paragraphs":["Growing sugar cane is primary. Processing cane at a mill is secondary. Shipping, retail and banking are tertiary. Compare sector importance using jobs, output, exports and links to other sectors."]},{"title":"Renewable and non-renewable resources","paragraphs":["Forests and fish can regenerate if harvest stays within their renewal rate. Oil, gas and bauxite are finite on human time scales. Caribbean examples include Jamaica''s bauxite, Trinidad and Tobago''s oil and gas, Guyana''s forests and fishing in Caribbean coastal waters. Locate the resource on a sketch map."]},{"title":"Explain a location","paragraphs":["Raw materials, electricity, transport, labour, capital, market and government policy all matter. A bauxite plant may need a mineral supply and bulk shipping. A factory selling perishable food may benefit from a nearby market, cold storage and reliable roads."]}],"workedExample":{"title":"Worked example","prompt":"A mill is built near cane fields and a road to port.","answer":"Short farm trips reduce transport time for bulky cane, and the port connection lowers the cost of moving processed sugar to markets."},"check":{"question":"Why can a renewable fish stock still decline?","answer":"Catches can exceed the rate at which fish reproduce and replenish the stock."},"flashcards":[{"id":"geo-resources-and-industry-check","front":"Why can a renewable fish stock still decline?","back":"Catches can exceed the rate at which fish reproduce and replenish the stock."},{"id":"geo-resources-and-industry-apply","front":"A mill is built near cane fields and a road to port.","back":"Short farm trips reduce transport time for bulky cane, and the port connection lowers the cost of moving processed sugar to markets."}]}}'::jsonb),
  ('geography', 'geo-tourism-and-sustainability', 'geo-human-systems', 'Caribbean tourism and industry trade-offs', 'Tourism grows where attractions, access and services make visits possible.', 22, true, '{"syllabus":{"objectives":["III 13–15"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Tourism grows where attractions, access and services make visits possible.","sections":[{"title":"Location and growth","paragraphs":["Beaches, reefs, culture, heritage and weather attract visitors. Airports, cruise ports, accommodation, marketing, investment and trained workers connect those attractions to markets. Name a place such as Montego Bay and explain how physical and human factors work together."]},{"title":"Costs and benefits","paragraphs":["Tourism can create jobs, earn foreign exchange and buy local food or services. Profits can leak overseas if businesses import supplies or remit earnings. Seasonal jobs and exposure to storms or overseas demand can cause income swings. Wastewater, high water demand and reef damage are local pressures."]},{"title":"Evaluate responses","paragraphs":["Local sourcing can retain more spending. Wastewater treatment and visitor limits can protect an attraction. Diversifying the economy can reduce dependence on one industry. For other industries, include specific measures such as mine rehabilitation, cleaner processing or monitoring effluent."]}],"workedExample":{"title":"Worked example","prompt":"A reef resort buys fish from overseas and has a failing sewage system.","answer":"Local sourcing can increase community income if fish stocks are managed. Upgrading sewage treatment helps protect the reef that attracts visitors."},"check":{"question":"How can tourism increase foreign exchange while creating limited local income?","answer":"Visitors spend foreign currency, but imports and overseas profit transfers can take a large share out of the local economy."},"flashcards":[{"id":"geo-tourism-and-sustainability-check","front":"How can tourism increase foreign exchange while creating limited local income?","back":"Visitors spend foreign currency, but imports and overseas profit transfers can take a large share out of the local economy."},{"id":"geo-tourism-and-sustainability-apply","front":"A reef resort buys fish from overseas and has a failing sewage system.","back":"Local sourcing can increase community income if fish stocks are managed. Upgrading sewage treatment helps protect the reef that attracts visitors."}]}}'::jsonb),
  ('geography', 'geo-agriculture', 'geo-human-systems', 'Caribbean farming and sugar cane in Guyana and Brazil', 'Farm patterns depend on land, climate, labour, history, markets, finance and the technology farmers can use.', 23, true, '{"syllabus":{"objectives":["III 16–20"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"Farm patterns depend on land, climate, labour, history, markets, finance and the technology farmers can use.","sections":[{"title":"Compare farm sizes in one territory","paragraphs":["Large commercial farms often use more land, capital, equipment and processing links. Small farms can use family labour, grow several crops and sell to local markets. In Guyana, coastal lowlands support commercial agriculture where drainage and irrigation make cultivation possible. In Jamaica, identify contrasting farms and crops using a named locality."]},{"title":"Compare sugar cane","paragraphs":["In Guyana, many cane-growing areas lie on flat coastal land with drainage and irrigation canals. Uitvlugt Estate on the West Coast of Demerara is a named example. GuySuCo describes its irrigation and navigation waterways as supplied from the Boeraserie Conservancy. Brazil has extensive production in areas including São Paulo, with large mechanised operations and strong sugar and ethanol industries. Compare acreage, labour, technology and markets under matching headings. Use dated sources for production statistics."]},{"title":"Explain changes and their effects","paragraphs":["Mechanisation can raise output per worker but reduce manual jobs. Irrigation can stabilise production while increasing water demand. Export markets and trade changes affect prices and crop choices. Clearing land can increase erosion or habitat loss. Explain how the same change affects people and the environment."]}],"workedExample":{"title":"Worked example","prompt":"Two farms replace manual harvesting with machines.","answer":"Production may become faster where field layout suits the machines. Labour demand can fall or shift to operators and mechanics. Smaller farmers may have difficulty financing equipment."},"check":{"question":"What makes a good comparison of Guyana and Brazil sugar production?","answer":"Compare the same feature in both places and explain a relevant difference in conditions, methods or markets."},"flashcards":[{"id":"geo-agriculture-check","front":"What makes a good comparison of Guyana and Brazil sugar production?","back":"Compare the same feature in both places and explain a relevant difference in conditions, methods or markets."},{"id":"geo-agriculture-apply","front":"Two farms replace manual harvesting with machines.","back":"Production may become faster where field layout suits the machines. Labour demand can fall or shift to operators and mechanics. Smaller farmers may have difficulty financing equipment."}]}}'::jsonb),
  ('geography', 'geo-resources-and-environment', 'geo-human-systems', 'Environmental degradation and sustainable management', 'A sustainable decision manages the resource, the people who rely on it and the effects on other places.', 24, true, '{"syllabus":{"objectives":["III 21–22"],"sourceUrl":"https://www.cxc.org/wp-content/uploads/2018/11/CSEC-GEOGRAPHY-SYLLABUS-Revised-2015.pdf"},"lesson":{"introduction":"A sustainable decision manages the resource, the people who rely on it and the effects on other places.","sections":[{"title":"Connect activity to damage","paragraphs":["Deforestation removes protective cover and can increase soil loss. Fertiliser runoff can add nutrients to water, increasing algal growth and reducing oxygen as algae decay. Mining can remove habitat and leave spoil. Poorly managed waste can block drains and contaminate water."]},{"title":"Choose a measure that fits","paragraphs":["Replant mined land and manage runoff before it reaches streams. Use contour planting or vegetated buffers to slow soil loss. Protect spawning areas and set catch limits to allow fisheries to recover. Repair leaks, harvest rainwater and protect watersheds to improve freshwater reliability."]},{"title":"Compare scales and judge progress","paragraphs":["A community can monitor a beach or stream. A government can set and enforce standards. Caribbean cooperation can help manage shared fisheries, pollution and disaster risk. Use evidence such as turbidity, fish size, water use or vegetation cover to check whether a measure works."]}],"workedExample":{"title":"Worked example","prompt":"A town wants to reduce flooding and pollution in the same river.","answer":"Regular waste collection reduces blocked drains. A restored riverside buffer traps some sediment and slows runoff. Monitor river water and flood frequency at comparable rainfall levels."},"check":{"question":"Why should a sustainability answer include a way to measure success?","answer":"The measure makes it possible to test whether the intervention actually improved the resource or reduced the harm."},"flashcards":[{"id":"geo-resources-and-environment-check","front":"Why should a sustainability answer include a way to measure success?","back":"The measure makes it possible to test whether the intervention actually improved the resource or reduced the harm."},{"id":"geo-resources-and-environment-apply","front":"A town wants to reduce flooding and pollution in the same river.","back":"Regular waste collection reduces blocked drains. A restored riverside buffer traps some sediment and slows runoff. Monitor river water and flood frequency at comparable rainfall levels."}]}}'::jsonb)
